const fs = require('fs');

// Inspector-reported values (from the four dependency reports) to be verified, not trusted.
const inspected = {
  north: { count: 10, units: 90,  weighted: 167 },
  south: { count: 10, units: 94,  weighted: 171 },
  east:  { count: 10, units: 98,  weighted: 209 },
  west:  { count: 10, units: 85,  weighted: 145 },
};
const order = ['north', 'south', 'east', 'west'];

let allOk = true;
const regions = {};
const report = {};

for (const name of order) {
  const file = name + '.json';
  const raw = fs.readFileSync(file, 'utf8');
  let data;
  try { data = JSON.parse(raw); } catch (e) { throw new Error(file + ' is not valid JSON: ' + e.message); }
  if (!Array.isArray(data)) throw new Error(file + ' is not a JSON array');
  if (data.length === 0) throw new Error(file + ' is empty');

  let count = 0, units = 0, weighted = 0, bad = [];
  const seen = new Set();
  for (let i = 0; i < data.length; i++) {
    const r = data[i];
    const okShape = r !== null && typeof r === 'object' && !Array.isArray(r) &&
      Number.isInteger(r.id) && typeof r.units === 'number' && Number.isFinite(r.units) &&
      typeof r.weight === 'number' && Number.isFinite(r.weight);
    if (!okShape) { bad.push('record index ' + i + ' malformed: ' + JSON.stringify(r)); continue; }
    if (seen.has(r.id)) bad.push('duplicate id ' + r.id);
    seen.add(r.id);
    count++; units += r.units; weighted += r.units * r.weight;
  }
  // completeness: ids must be exactly 1..N with no gaps
  const ids = data.filter(r => r && Number.isInteger(r.id)).map(r => r.id).sort((a,b)=>a-b);
  const contiguous = ids.length === data.length && ids.every((v, i) => v === i + 1);
  if (!contiguous) bad.push('ids not contiguous 1..N: ' + JSON.stringify(ids));
  // recompute via reduce as an independent second method inside Node
  const unitsReduce = data.reduce((a, r) => a + r.units, 0);
  const weightedReduce = data.reduce((a, r) => a + r.units * r.weight, 0);
  if (unitsReduce !== units || weightedReduce !== weighted) bad.push('loop/reduce mismatch');

  const insp = inspected[name];
  const match = insp.count === count && insp.units === units && insp.weighted === weighted;
  if (!match || bad.length) allOk = false;

  regions[name] = { count, units, weighted };
  report[name] = {
    file, bytes: raw.length, records: data.length,
    computed: { count, units, weighted },
    inspector: insp,
    inspectorMatch: match,
    idsContiguous: contiguous,
    keysPresent: data.every(r => r && ['id','units','weight'].every(k => Object.prototype.hasOwnProperty.call(r, k))),
    problems: bad,
  };
}

const grand_units = order.reduce((a, k) => a + regions[k].units, 0);
const grand_weighted = order.reduce((a, k) => a + regions[k].weighted, 0);

const answer = { regions, grand_units, grand_weighted };
fs.writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\n', 'utf8');

console.log(JSON.stringify({ perRegion: report, grand_units, grand_weighted, allOk }, null, 2));
if (!allOk) { console.error('VERIFICATION FAILED - answer.json written but inspector mismatch/completeness problem detected'); process.exit(1); }
console.log('VERIFICATION OK: all four Node recomputations match inspector reports; completeness checks passed');
EOF

